NAMES = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}
def note_to_midi(name):
    pc = NAMES[name[0]]
    i = 1
    while i < len(name) - 1:
        if name[i] == "#":
            pc = pc + 1
        elif name[i] == "b":
            pc = pc - 1
        i = i + 1
    octave = int(name[len(name) - 1])
    return 12 * (octave + 1) + pc

