practice.solution:
def triad_quality(a, b, c):
    x = (b - a) % 12
    y = (c - b) % 12
    if x == 4 and y == 3:
        return "major"
    if x == 3 and y == 4:
        return "minor"
    if x == 3 and y == 3:
        return "dim"
    if x == 4 and y == 4:
        return "aug"
    return "other"

