def contour(pitches):
    out = []
    for i in range(1, len(pitches)):
        if pitches[i] > pitches[i - 1]:
            out.append("u")
        elif pitches[i] < pitches[i - 1]:
            out.append("d")
        else:
            out.append("s")
    return out

